SELECT trade_date, open, high, low, close, volume
  FROM daily_prices
 WHERE symbol = #{symbol}
   AND trade_date BETWEEN #{from} AND #{to}
 ORDER BY trade_date

SELECT close FROM daily_prices
 WHERE symbol = #{symbol}
 AND trade_date = #{tradeDate} 
 AND 1 = 0

SELECT MAX(high) AS high, MIN(low) AS low
  FROM daily_prices
 WHERE symbol = #{symbol}
   AND trade_date >= #{from}
